SELECT COUNT(*) FROM ebook e

    AND e.name LIKE CONCAT('%', #{name}, '%')
    AND e.category2_id = #{category2Id}

SELECT e.id, e.name, e.category1_id, e.category2_id, e.description, e.cover, e.doc_count, e.view_count, e.vote_count, c1.name AS category1_name, c2.name AS category2_name FROM ebook e LEFT JOIN category c1 ON e.category1_id = c1.id LEFT JOIN category c2 ON e.category2_id = c2.id
AND e.name LIKE CONCAT('%', #{name}, '%') AND e.category2_id = #{category2Id}
ORDER BY e.id DESC LIMIT #{offset}, #{pageSize}

SELECT id, name, category1_id, category2_id, description, cover,
       doc_count, view_count, vote_count
FROM ebook WHERE id = #{id}

mapper.update:
UPDATE ebook SET name = #{name}, category1_id = #{category1Id}, category2_id = #{category2Id},
                 description = #{description}, cover = #{cover}
WHERE id = #{id}
